import React, { useState } from 'react';
import { Form, Button, Alert, Row, Col } from 'react-bootstrap';
import { referenceFieldAtom } from '../../../Services/_states';
import { useRecoilState } from 'recoil';

const ReferenceForm = ({ onSubmitReference }) => {
  const [fields, setFields] = useRecoilState(referenceFieldAtom);
  const [showAddButton, setShowAddButton] = useState(true);
  const [validate, setValidate] = useState(false);

  const handleChange = (index, key, e) => {
    const { value } = e.target;
    const newFields = [...fields];
    if (index >= 0 && index < newFields.length) {
      newFields[index] = { ...newFields[index], [key]: value }; // Update the value for the given key
      setFields(newFields);
    } else {
      console.error('Invalid index provided.');
    }
    if (key === 'number' && isNaN(Number(value))) setValidate(false);
    else setValidate(true);
  };

  const handleAddField = () => {
    if (fields.length < 3) {
      setFields([...fields, { number: '', designation: '', name: '' }]);
    }
    if (fields.length === 2) {
      setShowAddButton(false);
    }
  };

  const handleRemoveField = (index) => {
    if (index >= 0 && index < fields.length) {
      const filteredFields = fields.filter((field, i) => i !== index); // Filter out the element at the specified index
      setFields(filteredFields);
      if (!showAddButton) setShowAddButton(true);
    } else {
      console.error('Invalid index provided.');
    }
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    onSubmitReference(fields);
  };

  return (
    <Form onSubmit={handleSubmit}>
      {fields?.map((field, index) => (
        <div key={index}>
          <Form.Group>
            <Form.Label className="my-2"> Reference {index + 1}</Form.Label>
            {fields.length > 1 && (
              <span
                className="delete-icon"
                color="black"
                style={{ cursor: 'pointer' }}
                onClick={() => handleRemoveField(index)}
              >
                <svg
                  xmlns="http://www.w3.org/2000/svg"
                  width="16"
                  height="16"
                  fill="currentColor"
                  className="bi bi-trash"
                  viewBox="0 0 16 16"
                >
                  <path d="M5.5 5.5A.5.5 0 0 1 6 6v6a.5.5 0 0 1-1 0V6a.5.5 0 0 1 .5-.5m2.5 0a.5.5 0 0 1 .5.5v6a.5.5 0 0 1-1 0V6a.5.5 0 0 1 .5-.5m3 .5a.5.5 0 0 0-1 0v6a.5.5 0 0 0 1 0z" />
                  <path d="M14.5 3a1 1 0 0 1-1 1H13v9a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V4h-.5a1 1 0 0 1-1-1V2a1 1 0 0 1 1-1H6a1 1 0 0 1 1-1h2a1 1 0 0 1 1 1h3.5a1 1 0 0 1 1 1zM4.118 4 4 4.059V13a1 1 0 0 0 1 1h6a1 1 0 0 0 1-1V4.059L11.882 4zM2.5 3h11V2h-11z" />
                </svg>{' '}
              </span>
            )}

            <Form.Control
              className="my-2"
              type="text"
              placeholder="Name"
              value={field?.name}
              onChange={(e) => handleChange(index, 'name', e)}
            />
            <Form.Control
              className="my-2"
              type="tel"
              placeholder="1234567890"
              maxLength={10}
              value={field?.number || ''}
              onChange={(e) => handleChange(index, 'number', e)}
            />
            {isNaN(Number(field?.number)) && (
              <Alert variant="danger">Please Input a Valid Number</Alert>
            )}
            <Form.Select
              className="my-2"
              aria-label="Designation"
              onChange={(e) => handleChange(index, 'designation', e)}
              value={field?.designation}
            >
              <option value={''}>Designation</option>
              {['Resident', 'Owner', 'Former Resident', 'Agent', 'Committee Member']?.map(
                (option, index) => (
                  <option key={index} value={option}>
                    {option}
                  </option>
                )
              )}
            </Form.Select>
          </Form.Group>
        </div>
      ))}
      <Row className="add-submit-btn">
        <Col className="button-row lead-web-form-btns" xs={10}>
          {showAddButton && (
            <Button variant="primary" className="btn" onClick={handleAddField}>
              Add
              {/* <svg
            xmlns="http://www.w3.org/2000/svg"
            width="16"
            height="16"
            fill="currentColor"
            className="bi bi-plus-square"
            viewBox="0 0 16 16"
          >
            <path d="M14 1a1 1 0 0 1 1 1v12a1 1 0 0 1-1 1H2a1 1 0 0 1-1-1V2a1 1 0 0 1 1-1zM2 0a2 2 0 0 0-2 2v12a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V2a2 2 0 0 0-2-2z" />
            <path d="M8 4a.5.5 0 0 1 .5.5v3h3a.5.5 0 0 1 0 1h-3v3a.5.5 0 0 1-1 0v-3h-3a.5.5 0 0 1 0-1h3v-3A.5.5 0 0 1 8 4" />
          </svg> */}
            </Button>
          )}
          <Button variant="primary" className="btn" type="submit" disabled={!validate}>
            Submit
          </Button>
        </Col>
      </Row>
    </Form>
  );
};

export default ReferenceForm;
